export const secretListShapes = [
    {
        command: "secret-list",
        handler: (result) => {
            const r = result;
            const secrets = Array.isArray(r.secrets) ? r.secrets : [];
            return {
                ...r,
                shape: r.shape ?? "secret-list",
                schemaVersion: r.schemaVersion ?? 1,
                secrets: secrets.map((s) => {
                    const { path: _path, ...rest } = s;
                    return rest;
                }),
            };
        },
    },
];
